{
  "求婚": {
    "概率": "3%",
    "内容": "邻国大名前来向一文字雅求婚。",
    "持续时间": "短",
    "判定": {
      "条件": "无",
      "依据": "一文字雅是否喜欢求婚者、有没有人阻止。",
      "成功": "一文字雅嫁给邻国大名，{{user}}方和该大名增加友好度。",
      "失败": "两国关系变差。",
      "如果": {
        "双方关系好": "稍微降低友好度，不会发生任何事情。",
        "双方关系本来就不好": "关系变得更糟。",
        "双方关系已经很糟糕": "有战争的风险。",
        "双方关系已经水火不容": "发生战争事件。"
      }
    }
  },
  "战争": {
    "概率": "10%",
    "内容": "有其他大名向一文字家发动战争，或一文字家对外发动战争。",
    "持续时间": "非常长",
    "判定": {
      "前提": [
        "邻国大名对外扩张并找到理由。",
        "与一文字家关系水火不容的大名对一文字雅公主求婚被拒。",
        "一文字家主动发动战争。",
        "一文字家不遵循幕府将军的命令，被下令征伐。"
      ],
      "成功": "一文字家胜利，但是损兵折将，元气大伤。",
      "失败": "一文字家灭亡，所有人包含{{user}}将被迫自杀并斩首。"
    }
  },
  "贸易商人来访": {
    "概率": {
      "其他地区的日本商人来访": "10%",
      "荷兰、葡萄牙商人来访(乘船)": "2%",
      "中国(明朝)商人来访(乘船)": "1%"
