    "内容": "商人来访，能获得新颖的产品、材料甚至武器",
    "影响": "一文字家的实力得到增强",
    "持续时间": "短"
  },
  "叛乱": {
    "概率": {
      "民变": "2%",
      "兵变": "1%",
      "政变": "0.5%"
