      "镇压成功": "相安无事，长时间不会再有叛乱",
      "镇压失败": "一文字家或一文字北虎(一文字北虎)的统治被推翻。"
    }
  },
  "暗杀": {
    "概率": {
      "暗杀将领": "2%",
      "暗杀{{user}}": "4%",
      "暗杀大名": "1%"
    },
    "前提": "与一位邻国大名关系水火不容。",
    "内容": "一文字家有人遭到暗杀，或是遭遇暗杀。",
    "持续时间": "非常短"
  },
  "传教": {
    "概率": {
      "本国传教士传教(神道教)": "7%",
      "本国传教士传教(佛教)": "7%",
      "葡萄牙传教士传教(天主教)": "4%"
    },
    "内容": "传教士来传教，可能改变一文字家的信仰",
    "持续时间": "中等",
    "影响": "一文字家改变宗教"
  },
  "奇人": {
    "概率": {
      "阴阳师(驱魔)": "2%",
      "奇术师(魔术)": "2%",
      "神医(古老的日本医学)": "2%",
      "戏剧": "4%"
    },
    "内容": "有拥有特别本领的人拜访一文字家，通常出现在城里而不是直接面见{{user}}或政府官员。",
    "持续时间": "短",
    "影响": "无"
  },
  "间谍": {
    "概率": "1%",
    "内容": "发现敌方间谍",
    "判定(任一)": {
      "前提": [
        "与一位邻国大名关系水火不容。",
        "与一位邻国大名处于战争状态。"
      ]
    },
    "细节": "间谍通常是忍者，但他们不会穿传统忍者装束。他们伪装成医生、演员、侍者或其他平民职业混在城中探查军情和民情，通常不会露出破绽，难以察觉。",
    "影响": "一文字家战败几率增加2%"
  },
  "异事": {
    "概率": {
      "佛教辩论对决": "1%",
      "奇异的天象": "1%",
      "闹鬼": "1%",
      "民间的有趣故事": "2%"
    },
    "内容": "发生有趣的事情，让故事更有趣",
    "影响": "无"
  },
  "天灾": {
    "概率": {
      "地震": "6%",
      "海啸": "0.5%",
      "饥荒": "2%"
    },
    "内容": "发生天灾，重创经济，民不聊生",
    "持续时间": "非常长",
    "影响": "可能影响一文字家的统治，或是重创经济"
  }
}

